#!/usr/bin/env python3
"""Constroi data/replay/v1: fonte de REPLAY (codigo JS/TS generico, licenca permissiva) e o conjunto `generic_js_fim_eval` (G2.5).

  C:/SlopStudio.MongoAI-artifacts/.venv/Scripts/python.exe -I scripts/data/build_replay.py [--roots-file R.json] [--out data/replay/v1]

Fonte: SOMENTE arquivos locais ja presentes no disco (node_modules globais/de apps/extensoes/caches do npm). Nada e baixado.
Licenca verificavel: campo `license` do package.json (SPDX: MIT, Apache-2.0, BSD-2/3-Clause, ISC; expressoes OR/AND avaliadas) confirmada
contra o arquivo LICENSE do pacote quando existe (texto GPL/AGPL/LGPL/proprietario rejeita o pacote). Exclusoes por arquivo: minificado/bundle
(> 200 caracteres medios por linha, linha > 1500), gerado, .d.ts, snapshots, < 15 ou > 2000 linhas, segredos (regex), texto GPL/proprietario.
Holdout por PACOTE (nome): pacotes de avaliacao nunca aparecem no replay_train; ainda se removem arquivos do treino com conteudo
compartilhado (shingles de 5 linhas nao-boilerplate) com os arquivos de avaliacao.
Saida: replay_train.jsonl, generic_js_fim_eval.jsonl (500 cortes FIM, middle <= 96 tokens Qwen), files.jsonl (inventario por arquivo),
manifest.json, LICENSES.md.
"""
from __future__ import annotations

import argparse
import collections
import hashlib
import json
import os
import random
import re
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(Path(__file__).resolve().parent))
import replay_cuts  # noqa: E402

TOKENIZER = ROOT / "BaseRepos" / "Qwen2.5-Coder-7B" / "tokenizer.json"
SEED = 20261008
EXTS = (".js", ".mjs", ".cjs", ".jsx", ".ts", ".tsx")
SKIP_DISK = {"$recycle.bin", "windows", "windows.old", "system volume information", "$sysreset", "winsxs", "recovery"}
EXCLUDE_SUBSTR = ("\\.git\\", "esilva", "kapibarastudio", "\\.codex\\worktrees\\")   # codigo proprietario/proprio do usuario
ALLOWED = {"MIT", "APACHE-2.0", "BSD-2-CLAUSE", "BSD-3-CLAUSE", "ISC"}
ALIASES = {"APACHE 2.0": "APACHE-2.0", "APACHE2": "APACHE-2.0", "APACHE-2": "APACHE-2.0", "APACHE LICENSE 2.0": "APACHE-2.0",
           "APACHE LICENSE, VERSION 2.0": "APACHE-2.0", "APACHE-2.0 WITH LLVM-EXCEPTION": "APACHE-2.0", "BSD-2": "BSD-2-CLAUSE",
           "BSD-3": "BSD-3-CLAUSE", "BSD": "BSD-?", "BSD*": "BSD-?", "MIT/X11": "MIT", "X11": "MIT", "(MIT)": "MIT", "BSD-3-CLAUSE-CLEAR": "BSD-?"}
LICENSE_FILES = ("LICENSE", "LICENSE.md", "LICENSE.txt", "LICENCE", "LICENCE.md", "LICENSE-MIT", "LICENSE-MIT.txt", "LICENSE.MIT",
                 "license", "license.md", "license.txt", "License.md", "License.txt", "LICENSE.markdown", "LICENSE-APACHE")

SECRET_RE = re.compile(
    r"-----BEGIN [A-Z ]*PRIVATE KEY-----|\bAKIA[0-9A-Z]{16}\b|\bghp_[A-Za-z0-9]{30,}|\bgho_[A-Za-z0-9]{30,}|\bxox[abprs]-[A-Za-z0-9-]{10,}|"
    r"\bAIza[0-9A-Za-z_\-]{35}\b|\bsk-[A-Za-z0-9]{32,}\b|\beyJ[A-Za-z0-9_-]{15,}\.eyJ[A-Za-z0-9_-]{15,}\.[A-Za-z0-9_-]{10,}|"
    r"(?i:(?:api[_-]?key|secret|token|passwd|password|private[_-]?key)[\"']?\s*[:=]\s*[\"'][A-Za-z0-9+/_\-]{20,}[\"'])")
COPYLEFT_RE = re.compile(r"GNU (?:Lesser |Affero )?General Public License|\bA?GPL-?[0-9]|\bLGPL\b|\bAGPL\b|\bGPLv[23]|proprietary and confidential|"
                         r"\bproprietary\b|\bconfidential\b|all rights reserved(?!\.?\s*\n?\s*(?:Licensed|Released|This file is licensed))(?=.*\bno part\b)",
                         re.I | re.S)
GENERATED_RE = re.compile(r"@generated|auto-?generated|automatically generated|do not edit|generated by |code generated|__webpack_require__|"
                          r"webpackBootstrap|sourceMappingURL=data:|\bSourceMappingURL=data", re.I)
LIC_TEXT = [("APACHE-2.0", re.compile(r"Apache License[\s,]+Version 2\.0", re.I)),
            ("MIT", re.compile(r"Permission is hereby granted, free of charge", re.I)),
            ("ISC", re.compile(r"Permission to use, copy, modify, and/or distribute this software for any purpose", re.I)),
            ("BSD-3-CLAUSE", re.compile(r"Redistribution and use in source and binary forms.*?Neither the name", re.I | re.S)),
            ("BSD-2-CLAUSE", re.compile(r"Redistribution and use in source and binary forms", re.I))]


def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def unit(salt: str, ident: str) -> int:
    return int.from_bytes(hashlib.sha256(f"{SEED}:{salt}:{ident}".encode()).digest()[:8], "big")


# -- descoberta -----------------------------------------------------------------------------------------------------------------
def discover_roots(drives=("C:\\", "D:\\", "E:\\")) -> list[str]:
    """node_modules (nao desce neles) + raizes de pacote fora de node_modules (diretorio com package.json; so a mais externa)."""
    out: list[str] = []
    for top in drives:
        for dp, dns, fns in os.walk(top, onerror=lambda e: None):
            if os.path.basename(dp) == "node_modules":
                out.append(dp)
                dns[:] = []
                continue
            low = dp.lower()
            if "package.json" in fns and not any(dp.startswith(r + "\\") for r in out if os.path.basename(r) != "node_modules"):
                out.append(dp)
            dns[:] = [d for d in dns if d.lower() not in SKIP_DISK and d != ".git"
                      and not any(x in (os.path.join(low, d.lower()) + "\\") for x in EXCLUDE_SUBSTR)]
    return sorted(out)


# -- licenca ----------------------------------------------------------------------------------------------------------------------
def spdx_ok(expr: str) -> tuple[bool, str]:
    """Avalia expressao SPDX simples. OR: basta uma alternativa permitida; AND: todas."""
    e = expr.strip().strip("()").strip()
    norm = ALIASES.get(e.upper(), e.upper())
    if " OR " in norm:
        parts = [spdx_ok(p)[0] for p in re.split(r"\s+OR\s+", norm)]
        return any(parts), expr
    if " AND " in norm:
        parts = [spdx_ok(p)[0] for p in re.split(r"\s+AND\s+", norm)]
        return all(parts), expr
    norm = norm.strip("() ")
    return norm in ALLOWED, norm


def license_field(pj: dict) -> str | None:
    lic = pj.get("license")
    if isinstance(lic, dict):
        lic = lic.get("type")
    if lic is None and isinstance(pj.get("licenses"), list) and pj["licenses"]:
        parts = [(x.get("type") if isinstance(x, dict) else str(x)) for x in pj["licenses"]]
        lic = " OR ".join(p for p in parts if p)
    return str(lic).strip() if lic else None


def detect_license_text(text: str) -> str | None:
    if re.search(r"GNU (?:LESSER |AFFERO )?GENERAL PUBLIC LICENSE|Mozilla Public License|Creative Commons|GPL", text, re.I):
        return "NON-PERMISSIVE"
    for name, rx in LIC_TEXT:
        if rx.search(text):
            return name
    return None


class PackageIndex:
    def __init__(self) -> None:
        self.cache: dict[str, dict | None] = {}

    def lookup(self, directory: str) -> dict | None:
        """Pacote que contem `directory`: package.json mais proximo com name+version (nao sobe alem de node_modules)."""
        chain = []
        d = directory
        found = None
        while True:
            if d in self.cache:
                found = self.cache[d]
                break
            chain.append(d)
            pj = os.path.join(d, "package.json")
            if os.path.isfile(pj):
                info = self._read(d, pj)
                if info is not None:
                    found = info
                    chain.pop()
                    self.cache[d] = info
                    break
            parent = os.path.dirname(d)
            if parent == d or os.path.basename(d) == "node_modules":
                break
            d = parent
        for c in chain:
            self.cache[c] = found
        return found

    @staticmethod
    def _read(d: str, pj: str) -> dict | None:
        try:
            raw = open(pj, "rb").read()
            data = json.loads(raw.decode("utf-8-sig"))
        except Exception:  # noqa: BLE001
            return None
        if not isinstance(data, dict) or not data.get("name") or not data.get("version"):
            return None
        field = license_field(data)
        lic_file, lic_class, lic_sha = None, None, None
        for name in LICENSE_FILES:
            p = os.path.join(d, name)
            if os.path.isfile(p):
                try:
                    lt = open(p, "rb").read()
                    text = lt.decode("utf-8", "replace")
                except OSError:
                    continue
                lic_file, lic_class, lic_sha = name, detect_license_text(text), sha256_bytes(lt)
                m = re.search(r"^.*Copyright.*$", text, re.I | re.M)
                copyright_line = m.group(0).strip()[:200] if m else None
                break
        else:
            copyright_line = None
        ok, license_final, source, reason = False, field, "package.json", None
        if field:
            ok, norm = spdx_ok(field)
            if ok and field.upper() in ("BSD", "BSD*"):
                ok = False
            if not ok and norm == "BSD-?" and lic_class in ALLOWED:
                ok, license_final, source = True, lic_class, "LICENSE(texto)"
            if ok and lic_class == "NON-PERMISSIVE":
                ok, reason = False, "LICENSE com texto nao permissivo"
            elif not ok:
                reason = f"license={field}"
        elif lic_class in ALLOWED:
            ok, license_final, source = True, lic_class, f"{lic_file}(texto)"
        else:
            reason = "sem campo license e LICENSE nao reconhecido"
        if ok and "node_modules" not in d.lower().split("\\"):
            # raiz fora de node_modules (app/extensao): o campo sozinho nao basta (ex.: ISC e o padrao do `npm init`); exige LICENSE permissivo
            if lic_class not in ALLOWED or data.get("private"):
                ok, reason = False, "raiz fora de node_modules sem LICENSE permissivo verificavel (ou private)"
        return {"name": data["name"], "version": str(data["version"]), "dir": d, "ok": ok, "license": license_final, "license_source": source,
                "reason": reason, "license_file": lic_file, "license_file_class": lic_class, "license_file_sha256": lic_sha,
                "copyright": copyright_line, "private": bool(data.get("private")), "homepage": data.get("homepage")}


# -- filtros por arquivo --------------------------------------------------------------------------------------------------------------
def file_filter(text: str, rel: str) -> tuple[bool, str]:
    lines = text.count("\n") + 1
    if lines < 15:
        return False, "lt15_lines"
    if lines > 2000:
        return False, "gt2000_lines"
    longest = max((len(x) for x in text.split("\n")), default=0)
    if len(text) / lines > 200 or longest > 1500:
        return False, "minified_or_bundle"
    if "\x00" in text:
        return False, "binary"
    if "// SIG // Begin signature block" in text:
        return False, "signed_block"
    if SECRET_RE.search(text):
        return False, "secret"
    if COPYLEFT_RE.search(text):
        return False, "copyleft_or_proprietary_text"
    if GENERATED_RE.search(text):
        return False, "generated"
    alnum = sum(c.isalnum() for c in text[:20000])
    if alnum / max(1, min(len(text), 20000)) < 0.45:
        return False, "low_alnum"
    return True, "ok"


SKIP_DIR_PARTS = ("__snapshots__", "\\.cache\\", "\\coverage\\", "\\.nyc_output\\")


def scan(roots: list[str]) -> tuple[list[dict], dict, dict]:
    idx = PackageIndex()
    cands: list[dict] = []
    rej = collections.Counter()
    lic_rej = collections.Counter()
    pkgs_seen: dict[tuple, dict] = {}
    t0 = time.time()
    for root in roots:
        for dp, dns, fns in os.walk(root, onerror=lambda e: None):
            low = dp.lower() + "\\"
            if any(x in low for x in EXCLUDE_SUBSTR) or any(s in low for s in SKIP_DIR_PARTS):
                dns[:] = []
                continue
            if os.path.basename(root) != "node_modules":   # raiz de pacote fora de node_modules: node_modules aninhados vem como raizes proprias
                dns[:] = [d for d in dns if d != "node_modules"]
            for fn in fns:
                if not fn.endswith(EXTS) or fn.endswith((".d.ts", ".d.mts", ".d.cts")) or ".min." in fn or fn.endswith((".snap", ".map")):
                    if fn.endswith(EXTS):
                        rej["d_ts_or_min"] += 1
                    continue
                path = os.path.join(dp, fn)
                pkg = idx.lookup(dp)
                if pkg is None:
                    rej["no_package"] += 1
                    continue
                pkgs_seen.setdefault((pkg["name"], pkg["version"], pkg["dir"]), pkg)
                if not pkg["ok"]:
                    rej["license_not_permissive"] += 1
                    lic_rej[str(pkg["reason"])[:60]] += 1
                    continue
                try:
                    raw = open(path, "rb").read()
                    text = raw.decode("utf-8")
                except (OSError, UnicodeDecodeError):
                    rej["unreadable_or_not_utf8"] += 1
                    continue
                if len(raw) > 400_000:
                    rej["gt_400kb"] += 1
                    continue
                text = text.replace("\r\n", "\n")
                ok, why = file_filter(text, path)
                if not ok:
                    rej[why] += 1
                    continue
                cands.append({"path": path, "package": pkg["name"], "version": pkg["version"], "license": pkg["license"],
                              "license_source": pkg["license_source"], "rel": os.path.relpath(path, pkg["dir"]).replace("\\", "/"),
                              "ext": os.path.splitext(fn)[1], "sha256": sha256_bytes(raw), "lines": text.count("\n") + 1,
                              "bytes": len(raw), "text": text, "pkg_dir": pkg["dir"]})
        print(f"  [{time.time() - t0:5.0f}s] {len(cands):6d} candidatos | {root}", flush=True)
    return cands, dict(rej), {"license_rejections": dict(lic_rej), "packages_seen": pkgs_seen}


def ver_key(v: str) -> tuple:
    return tuple(int(x) if x.isdigit() else 0 for x in re.split(r"[.\-+]", v)[:4])


def dedupe(cands: list[dict]) -> tuple[list[dict], dict]:
    """Uma versao por pacote (a maior); depois conteudo identico (sha256 e sha do texto sem espacos extremos)."""
    best: dict[str, tuple] = {}
    for c in cands:
        k = ver_key(c["version"])
        cur = best.get(c["package"])
        if cur is None or (k, c["pkg_dir"]) > cur:
            best[c["package"]] = (k, c["pkg_dir"], c["version"])
    stats = collections.Counter()
    out, seen, seen_rel = [], set(), set()
    for c in sorted(cands, key=lambda c: (c["package"], c["pkg_dir"], c["rel"])):
        if best[c["package"]][2] != c["version"] or best[c["package"]][1] != c["pkg_dir"]:
            stats["other_version_or_copy_of_package"] += 1
            continue
        norm = hashlib.sha256(re.sub(r"\s+", " ", c["text"]).strip().encode()).hexdigest()
        if norm in seen:
            stats["duplicate_content"] += 1
            continue
        if (c["package"], c["rel"]) in seen_rel:
            stats["duplicate_relpath"] += 1
            continue
        seen.add(norm)
        seen_rel.add((c["package"], c["rel"]))
        c["norm_sha256"] = norm
        out.append(c)
    return out, dict(stats)


def shingles(text: str, k: int = 5) -> set[int]:
    lines = [ln.strip() for ln in text.split("\n")]
    lines = [ln for ln in lines if len(ln) >= 25 and not ln.startswith(("//", "*", "/*", "#"))]
    return {hash(tuple(lines[i:i + k])) & 0x7FFFFFFFFFFFFFFF for i in range(max(0, len(lines) - k + 1))}


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--out", default=str(ROOT / "data" / "replay" / "v1"))
    ap.add_argument("--roots-file")
    ap.add_argument("--n-eval", type=int, default=500)
    ap.add_argument("--per-package-eval-cap", type=int, default=30)
    ap.add_argument("--per-package-train-token-share", type=float, default=0.03)
    ap.add_argument("--scan-only", action="store_true")
    args = ap.parse_args()
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    t0 = time.time()
    if args.roots_file:
        roots = json.loads(Path(args.roots_file).read_text(encoding="utf-8"))
        roots = [r for r in roots if not any(x in (r.lower() + "\\") for x in EXCLUDE_SUBSTR)]
    else:
        print("[1/6] descobrindo node_modules em C:, D:, E:", flush=True)
        roots = discover_roots()
    print(f"      {len(roots)} raizes node_modules", flush=True)
    print("[2/6] varrendo pacotes/arquivos", flush=True)
    cands, rej, extra = scan(roots)
    cands, dstats = dedupe(cands)
    tc = replay_cuts.Counter96(str(TOKENIZER))
    from tokenizers import Tokenizer
    tok = Tokenizer.from_file(str(TOKENIZER))
    print(f"[3/6] tokenizando {len(cands)} arquivos unicos", flush=True)
    for i in range(0, len(cands), 512):
        batch = cands[i:i + 512]
        for c, e in zip(batch, tok.encode_batch([c["text"] for c in batch], add_special_tokens=False)):
            c["tokens"] = len(e.ids)
    total_tokens = sum(c["tokens"] for c in cands)
    by_pkg: dict[str, list[dict]] = collections.defaultdict(list)
    for c in cands:
        by_pkg[c["package"]].append(c)
    print(f"      {len(by_pkg)} pacotes, {total_tokens:,} tokens", flush=True)
    if args.scan_only:
        top = sorted(by_pkg.items(), key=lambda kv: -sum(c["tokens"] for c in kv[1]))[:25]
        for name, fs in top:
            print(f"   {sum(c['tokens'] for c in fs):>10,} {len(fs):5d} {name}@{fs[0]['version']} {fs[0]['license']}")
        print(json.dumps({"rejections": rej, "dedupe": dstats, "lic_rej": extra["license_rejections"]}, indent=1))
        return 0

    # ---- holdout por pacote + avaliacao ---------------------------------------------------------------------------------
    print("[4/6] holdout por pacote e cortes FIM", flush=True)
    from compact import syntax
    order = sorted(by_pkg, key=lambda p: unit("eval-pkg", p))
    eval_pkgs: list[str] = []
    eval_files: list[dict] = []
    eval_tokens = 0
    parse_ok: dict[str, bool] = {}
    for name in order:
        js = [c for c in by_pkg[name] if c["ext"] in (".js", ".cjs") and c["tokens"] <= 12000]
        if not js:
            continue
        res = syntax.check_many([(c["sha256"], c["text"], "script") for c in js])
        js = [c for c in js if res[c["sha256"]][0]]
        if len(js) < 2:
            continue
        eval_pkgs.append(name)
        eval_files += js[: 10 * args.per_package_eval_cap]
        eval_tokens += sum(c["tokens"] for c in by_pkg[name])
        if len(eval_files) >= 4 * args.n_eval or eval_tokens > 0.20 * total_tokens:
            break
    eval_set = set(eval_pkgs)
    cuts: list[dict] = []
    per_pkg = collections.Counter()
    rng_order = sorted(eval_files, key=lambda c: unit("eval-file", c["sha256"]))
    tried = collections.Counter()
    for c in rng_order:
        if len(cuts) >= args.n_eval:
            break
        if per_pkg[c["package"]] >= args.per_package_eval_cap:
            continue
        rng = random.Random(f"{SEED}:cut:{c['sha256']}")
        cut = replay_cuts.make_cut(c["text"], rng, tc, max_tokens=96)
        tried[c["package"]] += 1
        if cut is None:
            continue
        doc = cut["prefix"] + cut["middle"] + cut["suffix"]
        assert doc == c["text"]
        n = len(cuts)
        cuts.append({"id": f"gjs-{n:04d}-{c['sha256'][:10]}", "type": "fim", "task": "autocomplete", "dialect": "js", "split": "eval",
                     "prefix": cut["prefix"], "suffix": cut["suffix"], "middle": cut["middle"], "target": cut["middle"],
                     "cut_kind": cut["cut_kind"], "cursor_role": cut["cursor_role"], "mid_token": cut["mid_token"],
                     "multiline": cut["multiline"], "middle_tokens": tc.count(cut["middle"]), "domain": c["package"],
                     "package": c["package"], "version": c["version"], "license": c["license"], "path": c["rel"],
                     "file_sha256": c["sha256"]})
        per_pkg[c["package"]] += 1
    cuts.sort(key=lambda r: r["id"])
    # monitor de treino (100 cortes de OUTROS arquivos dos mesmos pacotes holdout): val_loss/gen durante o SFT; nao e o conjunto do G2.5
    used_files = {r["file_sha256"] for r in cuts}
    monitor: list[dict] = []
    mon_pkg = collections.Counter()
    for c in rng_order:
        if len(monitor) >= 100:
            break
        if c["sha256"] in used_files or mon_pkg[c["package"]] >= 4:
            continue
        cut = replay_cuts.make_cut(c["text"], random.Random(f"{SEED}:monitor:{c['sha256']}"), tc, max_tokens=96)
        if cut is None:
            continue
        mon_pkg[c["package"]] += 1
        monitor.append({"id": f"gjsm-{len(monitor):04d}-{c['sha256'][:10]}", "type": "fim", "task": "autocomplete", "dialect": "js",
                        "split": "monitor", "prefix": cut["prefix"], "suffix": cut["suffix"], "middle": cut["middle"], "target": cut["middle"],
                        "cut_kind": cut["cut_kind"], "cursor_role": cut["cursor_role"], "mid_token": cut["mid_token"],
                        "multiline": cut["multiline"], "middle_tokens": tc.count(cut["middle"]), "domain": c["package"],
                        "package": c["package"], "version": c["version"], "license": c["license"], "path": c["rel"],
                        "file_sha256": c["sha256"]})
    print(f"      holdout: {len(eval_pkgs)} pacotes, {len(eval_files)} arquivos JS parseaveis, {eval_tokens:,} tokens; cortes {len(cuts)} "
          f"(tentados {sum(tried.values())})", flush=True)
    if len(cuts) < args.n_eval:
        print(f"AVISO: so {len(cuts)} cortes (alvo {args.n_eval})", flush=True)
    eval_used_pkgs = sorted({r["package"] for r in cuts})

    # ---- treino: pacotes fora do holdout, sem conteudo compartilhado, com teto por pacote -----------------------------------------
    print("[5/6] construindo replay_train (sem sobreposicao com a avaliacao)", flush=True)
    eval_pkg_all = set(eval_pkgs)
    eval_sh: dict[int, set] = collections.defaultdict(set)
    for name in eval_pkg_all:
        for c in by_pkg[name]:
            for s in shingles(c["text"]):
                eval_sh[s].add(name)
    train_cands = [c for p, fs in by_pkg.items() if p not in eval_pkg_all for c in fs]
    train_sh = {c["sha256"]: shingles(c["text"]) for c in train_cands}
    pkg_count: dict[int, set] = collections.defaultdict(set)
    for c in train_cands:
        for s in train_sh[c["sha256"]]:
            if s in eval_sh:
                pkg_count[s].add(c["package"])
    dropped_overlap = []
    kept = []
    eval_norm = {c["norm_sha256"] for p in eval_pkg_all for c in by_pkg[p]}
    for c in train_cands:
        shared = [s for s in train_sh[c["sha256"]] if s in eval_sh and len(pkg_count[s]) <= 3]
        if c["norm_sha256"] in eval_norm or len(shared) >= 3:
            dropped_overlap.append(c)
            continue
        kept.append(c)
    # teto por pacote (tokens) para nenhum pacote dominar
    train_total = sum(c["tokens"] for c in kept)
    cap = int(args.per_package_train_token_share * train_total)
    taken: dict[str, int] = collections.Counter()
    train_docs = []
    for c in sorted(kept, key=lambda c: unit("train-file", c["sha256"])):
        if taken[c["package"]] + c["tokens"] > cap:
            continue
        taken[c["package"]] += c["tokens"]
        train_docs.append(c)
    train_docs.sort(key=lambda c: (c["package"], c["rel"]))

    def dump(path: Path, rows: list[dict]) -> str:
        with path.open("w", encoding="utf-8", newline="\n") as h:
            for r in rows:
                h.write(json.dumps(r, ensure_ascii=False) + "\n")
        return sha256_bytes(path.read_bytes())

    train_rows = [{"id": f"rpl-{c['sha256'][:16]}", "text": c["text"], "package": c["package"], "version": c["version"], "license": c["license"],
                   "path": c["rel"], "ext": c["ext"], "sha256": c["sha256"], "lines": c["lines"], "tokens": c["tokens"], "split": "replay_train"}
                  for c in train_docs]
    sha_train = dump(out / "replay_train.jsonl", train_rows)
    sha_eval = dump(out / "generic_js_fim_eval.jsonl", cuts)
    sha_monitor = dump(out / "generic_js_fim_monitor.jsonl", monitor)
    inv = [{"role": "eval_holdout" if c["package"] in eval_pkg_all else "replay_train", "package": c["package"], "version": c["version"],
            "license": c["license"], "license_source": c["license_source"], "path": c["path"], "rel": c["rel"], "sha256": c["sha256"],
            "lines": c["lines"], "tokens": c["tokens"], "in_replay_train": c in train_docs if c["package"] not in eval_pkg_all else False}
           for c in cands]
    # `in_replay_train` por identidade de dict e O(n^2); recalcula por conjunto
    train_ids = {c["sha256"] for c in train_docs}
    for r in inv:
        r["in_replay_train"] = r["role"] == "replay_train" and r["sha256"] in train_ids
    sha_inv = dump(out / "files.jsonl", inv)

    # ---- manifest + LICENSES -----------------------------------------------------------------------------------------------------
    print("[6/6] manifest e LICENSES.md", flush=True)
    pk = extra["packages_seen"]
    pkg_rows = []
    for name in sorted(by_pkg):
        fs = by_pkg[name]
        info = pk[(name, fs[0]["version"], fs[0]["pkg_dir"])]
        role = "eval_holdout" if name in eval_pkg_all else "replay_train"
        used = [c for c in fs if c["sha256"] in train_ids] if role == "replay_train" else [c for c in fs]
        pkg_rows.append({"package": name, "version": fs[0]["version"], "license": info["license"], "license_source": info["license_source"],
                         "license_file": info["license_file"], "license_file_sha256": info["license_file_sha256"], "copyright": info["copyright"],
                         "role": role, "files_scanned_ok": len(fs), "files_used": len(used), "tokens_used": sum(c["tokens"] for c in used),
                         "source_dir": info["dir"]})
    train_tokens = sum(c["tokens"] for c in train_docs)
    lang = collections.Counter()
    for c in train_docs:
        lang["ts" if c["ext"] in (".ts", ".tsx") else "js"] += c["tokens"]
    manifest = {
        "schema": "replay/1", "built_utc": time.strftime("%FT%TZ", time.gmtime()), "seed": SEED,
        "builder_sha256": sha256_bytes(Path(__file__).read_bytes()), "cuts_sha256": sha256_bytes((Path(__file__).parent / "replay_cuts.py").read_bytes()),
        "tokenizer": {"path": str(TOKENIZER.relative_to(ROOT)), "sha256": sha256_bytes(TOKENIZER.read_bytes())},
        "sources": {"policy": "somente disco local (C:, D:, E:); F:\\source\\esilva-silva e data\\ do projeto excluidos; nada baixado",
                    "node_modules_roots": roots},
        "filters": {"allowed_licenses": sorted(ALLOWED), "lines": [15, 2000], "mean_chars_per_line_max": 200, "max_line_chars": 1500,
                    "max_bytes": 400000, "excluded": ["minified/bundle", "generated", ".d.ts", "snapshots", "secrets", "copyleft/proprietary text",
                                                      "one version per package", "duplicate content"]},
        "rejections": rej, "license_rejections_top": dict(collections.Counter(extra["license_rejections"]).most_common(25)), "dedupe": dstats,
        "totals": {"unique_files": len(cands), "unique_packages": len(by_pkg), "tokens_unique_files": total_tokens,
                   "replay_train": {"files": len(train_docs), "packages": len({c["package"] for c in train_docs}), "tokens": train_tokens,
                                    "tokens_by_lang": dict(lang), "dropped_content_overlap_with_eval": len(dropped_overlap),
                                    "per_package_token_cap": cap, "sha256": sha_train},
                   "generic_js_fim_monitor": {"cuts": len(monitor), "sha256": sha_monitor,
                                              "note": "outros arquivos dos pacotes holdout; so monitoramento do treino"},
                   "generic_js_fim_eval": {"cuts": len(cuts), "packages": len(eval_used_pkgs), "holdout_packages": len(eval_pkg_all),
                                           "cut_kind": dict(collections.Counter(r["cut_kind"] for r in cuts)),
                                           "middle_tokens_max": max((r["middle_tokens"] for r in cuts), default=0),
                                           "middle_tokens_mean": round(sum(r["middle_tokens"] for r in cuts) / max(1, len(cuts)), 1),
                                           "sha256": sha_eval, "reference_parses_as_script": True}},
        "isolation": {"package_overlap_train_x_eval": sorted({c["package"] for c in train_docs} & eval_pkg_all),
                      "file_sha256_overlap_train_x_eval": len({c["sha256"] for c in train_docs} & {r["file_sha256"] for r in cuts}),
                      "normalized_content_overlap": len({c["norm_sha256"] for c in train_docs} & eval_norm)},
        "files_index": {"file": "files.jsonl", "sha256": sha_inv, "rows": len(inv)},
        "packages": pkg_rows, "elapsed_s": round(time.time() - t0, 1),
    }
    (out / "manifest.json").write_text(json.dumps(manifest, indent=1, ensure_ascii=False) + "\n", encoding="utf-8", newline="\n")
    L = ["# Atribuicao de licencas - data/replay/v1", "",
         "Codigo de terceiros usado SOMENTE como replay de treino/avaliacao local (nao redistribuido; `data/replay/` e gitignored). Todas as licencas",
         "abaixo sao permissivas (MIT, Apache-2.0, BSD-2/3-Clause, ISC) e exigem preservar o aviso de copyright/licenca: os arquivos sao usados",
         "com o cabecalho original intacto. Fonte: `node_modules` ja instalados neste computador (caminho em `manifest.json`).", "",
         "| pacote | versao | licenca | origem da licenca | copyright | uso | arquivos | tokens |", "|---|---|---|---|---|---:|---:|---:|"]
    for r in pkg_rows:
        if r["files_used"] == 0 and r["role"] == "replay_train":
            continue
        L.append(f"| {r['package']} | {r['version']} | {r['license']} | {r['license_source']} | {(r['copyright'] or '-').replace('|', '/')} | "
                 f"{r['role']} | {r['files_used']} | {r['tokens_used']} |")
    (out / "LICENSES.md").write_text("\n".join(L) + "\n", encoding="utf-8", newline="\n")
    print(json.dumps({k: v for k, v in manifest["totals"].items()}, indent=1))
    print("isolation:", manifest["isolation"])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
